edges = [(0,3),(0,4),(0,5),(0,6),(1,3),(1,4),(1,5),(1,6),(2,3),(2,4),(2,5),(2,6)]

# Check triangle-free
n = 7
adj = [set() for _ in range(n)]
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

triangles = []
for u in range(n):
    for v in adj[u]:
        if v > u:
            for w in adj[v]:
                if w > v and w in adj[u]:
                    triangles.append((u,v,w))
print("Triangles:", triangles)

# Check maximality: for every non-edge, adding it creates a triangle
non_edges = []
for u in range(n):
    for v in range(u+1, n):
        if v not in adj[u]:
            non_edges.append((u,v))
print("Non-edges:", non_edges)

maximal = True
for u,v in non_edges:
    common = adj[u] & adj[v]
    if not common:
        print(f"Adding ({u},{v}) does NOT create a triangle")
        maximal = False
print("Maximal:", maximal)

# Check fixed edges
print("(0,6) present:", (0,6) in edges or (6,0) in edges)
print("(1,5) present:", (1,5) in edges or (5,1) in edges)
